import 'package:flutter/material.dart';
import 'package:url_launcher/url_launcher.dart';

class UrlLauncherExample extends StatelessWidget {
  const UrlLauncherExample({super.key});

  // 웹 URL 열기
  Future<void> _launchWebUrl() async {
    final Uri url = Uri.parse('https://flutter.dev');

    // 1. URL을 열 수 있는지 확인 (선택적이지만 권장)
    if (!await canLaunchUrl(url)) {
      throw Exception('Could not launch $url');
    }

    // 2. URL 열기
    await launchUrl(url);
  }

  // 외부 브라우저로 열기
  Future<void> _launchInBrowser() async {
    final Uri url = Uri.parse('https://flutter.dev');

    await launchUrl(
      url,
      mode: LaunchMode.externalApplication, // 외부 브라우저
    );
  }

  // 인앱 브라우저로 열기 (iOS Safari ViewController, Android Custom Tabs)
  Future<void> _launchInAppBrowser() async {
    final Uri url = Uri.parse('https://flutter.dev');

    await launchUrl(
      url,
      mode: LaunchMode.inAppBrowserView, // 인앱 브라우저
    );
  }

  // 인앱 WebView로 열기
  Future<void> _launchInWebView() async {
    final Uri url = Uri.parse('https://flutter.dev');

    await launchUrl(
      url,
      mode: LaunchMode.inAppWebView, // 인앱 WebView
      webViewConfiguration: const WebViewConfiguration(
        enableJavaScript: true,
        enableDomStorage: true,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('URL Launcher')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            ElevatedButton(
              onPressed: _launchWebUrl,
              child: const Text('기본으로 열기'),
            ),
            const SizedBox(height: 16),
            ElevatedButton(
              onPressed: _launchInBrowser,
              child: const Text('외부 브라우저로 열기'),
            ),
            const SizedBox(height: 16),
            ElevatedButton(
              onPressed: _launchInAppBrowser,
              child: const Text('인앱 브라우저로 열기'),
            ),
            const SizedBox(height: 16),
            ElevatedButton(
              onPressed: _launchInWebView,
              child: const Text('WebView로 열기'),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:url_launcher/url_launcher.dart';

class UrlSchemeExamples {

  // ===== 전화 걸기 =====
  // tel: 스킴 사용
  static Future<void> makePhoneCall(String phoneNumber) async {
    // 하이픈, 공백 제거
    final cleanNumber = phoneNumber.replaceAll(RegExp(r'[^0-9+]'), '');
    final Uri uri = Uri.parse('tel:$cleanNumber');

    if (await canLaunchUrl(uri)) {
      await launchUrl(uri);
    } else {
      throw Exception('전화를 걸 수 없습니다: $phoneNumber');
    }
  }

  // ===== 이메일 보내기 =====
  // mailto: 스킴 사용 - 제목, 본문 포함 가능
  static Future<void> sendEmail({
    required String to,
    String? subject,
    String? body,
    List<String>? cc,
    List<String>? bcc,
  }) async {
    final Uri uri = Uri(
      scheme: 'mailto',
      path: to,
      queryParameters: {
        if (subject != null) 'subject': subject,
        if (body != null) 'body': body,
        if (cc != null && cc.isNotEmpty) 'cc': cc.join(','),
        if (bcc != null && bcc.isNotEmpty) 'bcc': bcc.join(','),
      },
    );

    if (await canLaunchUrl(uri)) {
      await launchUrl(uri);
    } else {
      throw Exception('이메일을 보낼 수 없습니다');
    }
  }

  // ===== SMS 보내기 =====
  // sms: 스킴 사용
  static Future<void> sendSms(String phoneNumber, {String? message}) async {
    final Uri uri = Uri(
      scheme: 'sms',
      path: phoneNumber,
      queryParameters: message != null ? {'body': message} : null,
    );

    if (await canLaunchUrl(uri)) {
      await launchUrl(uri);
    } else {
      throw Exception('SMS를 보낼 수 없습니다');
    }
  }

  // ===== 지도 열기 (Google Maps) =====
  static Future<void> openMap(double latitude, double longitude) async {
    final Uri googleMapsUri = Uri.parse(
      'https://www.google.com/maps/search/?api=1&query=$latitude,$longitude'
    );

    await launchUrl(
      googleMapsUri,
      mode: LaunchMode.externalApplication,
    );
  }

  // ===== 앱스토어 열기 =====
  static Future<void> openAppStore(String appId, {bool isIOS = true}) async {
    final Uri uri = isIOS
        ? Uri.parse('https://apps.apple.com/app/id$appId')
        : Uri.parse('https://play.google.com/store/apps/details?id=$appId');

    await launchUrl(uri, mode: LaunchMode.externalApplication);
  }
}

// 사용 예시
void example() async {
  // 전화
  await UrlSchemeExamples.makePhoneCall('010-1234-5678');

  // 이메일
  await UrlSchemeExamples.sendEmail(
    to: 'support@example.com',
    subject: '문의합니다',
    body: '안녕하세요, 문의 내용입니다.',
  );

  // SMS
  await UrlSchemeExamples.sendSms('010-1234-5678', message: '안녕하세요!');

  // 지도
  await UrlSchemeExamples.openMap(37.5665, 126.9780); // 서울시청
}

import 'package:flutter/material.dart';
import 'package:url_launcher/url_launcher.dart';

/// URL 실행 결과
enum LaunchResult {
  success,
  cannotLaunch,
  invalidUrl,
  error,
}

/// URL Launcher 유틸리티
class UrlLauncherUtil {

  /// 웹 URL 열기 (에러 처리 포함)
  static Future<LaunchResult> openUrl(
    String url, {
    LaunchMode mode = LaunchMode.platformDefault,
  }) async {
    try {
      // URL 유효성 검사
      final Uri? uri = Uri.tryParse(url);
      if (uri == null || !uri.hasScheme) {
        return LaunchResult.invalidUrl;
      }

      // http -> https 자동 변환 (보안)
      final Uri secureUri = uri.scheme == 'http'
          ? uri.replace(scheme: 'https')
          : uri;

      // 실행 가능 여부 확인
      if (!await canLaunchUrl(secureUri)) {
        return LaunchResult.cannotLaunch;
      }

      // URL 열기
      final bool launched = await launchUrl(secureUri, mode: mode);
      return launched ? LaunchResult.success : LaunchResult.error;

    } catch (e) {
      debugPrint('URL 열기 실패: $e');
      return LaunchResult.error;
    }
  }

  /// 전화 걸기
  static Future<LaunchResult> call(String phoneNumber) async {
    final cleanNumber = phoneNumber.replaceAll(RegExp(r'[^0-9+]'), '');
    if (cleanNumber.isEmpty) return LaunchResult.invalidUrl;

    return _launch(Uri.parse('tel:$cleanNumber'));
  }

  /// 이메일 보내기
  static Future<LaunchResult> email({
    required String to,
    String? subject,
    String? body,
  }) async {
    final Uri uri = Uri(
      scheme: 'mailto',
      path: to,
      queryParameters: {
        if (subject != null && subject.isNotEmpty) 'subject': subject,
        if (body != null && body.isNotEmpty) 'body': body,
      },
    );

    return _launch(uri);
  }

  /// SMS 보내기
  static Future<LaunchResult> sms(String phoneNumber, {String? message}) async {
    final cleanNumber = phoneNumber.replaceAll(RegExp(r'[^0-9+]'), '');
    if (cleanNumber.isEmpty) return LaunchResult.invalidUrl;

    final Uri uri = Uri(
      scheme: 'sms',
      path: cleanNumber,
      queryParameters: message != null ? {'body': message} : null,
    );

    return _launch(uri);
  }

  /// 내부 launch 헬퍼
  static Future<LaunchResult> _launch(Uri uri) async {
    try {
      if (!await canLaunchUrl(uri)) {
        return LaunchResult.cannotLaunch;
      }

      final bool launched = await launchUrl(uri);
      return launched ? LaunchResult.success : LaunchResult.error;
    } catch (e) {
      debugPrint('Launch 실패: $e');
      return LaunchResult.error;
    }
  }

  /// 결과에 따른 스낵바 표시
  static void showResultSnackBar(
    BuildContext context,
    LaunchResult result,
  ) {
    final String message = switch (result) {
      LaunchResult.success => '성공적으로 열었습니다',
      LaunchResult.cannotLaunch => '이 기능을 사용할 수 없습니다',
      LaunchResult.invalidUrl => '잘못된 URL입니다',
      LaunchResult.error => '오류가 발생했습니다',
    };

    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message)),
    );
  }
}

// 사용 예시
class ContactScreen extends StatelessWidget {
  const ContactScreen({super.key});

  void _handleCall(BuildContext context) async {
    final result = await UrlLauncherUtil.call('02-1234-5678');
